package metodos.de.sobrecarga.estudando.domain;public class Anime {    private String name;    private String type;    private String gender;    private int episodes;    public void imprimir() {        System.out.println(this.name);        System.out.println(this.type);        System.out.println(this.episodes);        System.out.println(this.gender);    }    public void init (String name, String type, int episodes){        this.name = name;        this.type = type;        this.episodes = episodes;    }    public void init2 (String name, String type, int episodes, String gender){        this.name = name;        this.type = type;        this.episodes = episodes;        this.gender = gender;    }    public String getName() {        return name;    }    public String getType() {        return type;    }    public int getEpisodes() {        return episodes;    }    public String getGender() {        return gender;    }    public void setGender(String gender) {        this.gender = gender;    }}